struct Handle: ~Copyable {
    let id: Int
    consuming func close() {
        print("Closed \(id)")
        discard self
    }
    deinit {
        print("Deinit \(id)")
    }
}

func run() {
    let h = Handle(id: 8)
    h.close()
}
run()

