struct CounterBox: ~Copyable {
    var count = 1
    mutating func bump() {
        count += 4
    }
    borrowing func show() {
        print(count)
    }
}

func run() {
    var box = CounterBox()
    box.bump()
    box.show()
}
run()

enum LockState: ~Copyable {
    case locked(id: Int)
    case unlocked
}

func readState(_ state: borrowing LockState) {
    switch state {
    case .locked(let id):
        print("L\(id)")
    case .unlocked:
        print("U")
    }
}

func run() {
    let s = LockState.locked(id: 9)
    readState(s)
    readState(s)
}
run()

