protocol Labelable: ~Copyable {
    borrowing func label() -> String
}

struct KeyCard: ~Copyable, Labelable {
    let id: Int
    borrowing func label() -> String { "Key \(id)" }
}

func printLabel<T: ~Copyable & Labelable>(_ item: borrowing T) {
    print(item.label())
}

func run() {
    let card = KeyCard(id: 7)
    printLabel(card)
}
run()
